import { HTMLAttributes } from "react"
import config from "../config"
import imageRegistry from "./registry"
import { getFileName, SIZES } from "./utils"

const FALLBACK_SIZE = 1280
const FALLBACK_FORMAT = "jpg"
const MODERN_FORMAT = "webp"

interface ImageProps extends HTMLAttributes<HTMLImageElement> {
    src: string
    alt: string
    width?: number
    height?: number
    className?: string
    wrapperClassName?: string
    loading?: "lazy" | "eager"
    sizes?: string
}

function generateSrc(name: string, size: (typeof SIZES)[number]) {
    return `${config.imgDir}/${name} ${size}w`
}

function generateSrcSet(src: string, format: "webp" | "jpg"): string {
    return SIZES.map((size) => {
        const name = getFileName(src, size, format)
        return generateSrc(name, size)
    }).join(", ")
}

function generateFallbackSrc(src: string) {
    return generateSrc(
        getFileName(src, FALLBACK_SIZE, FALLBACK_FORMAT),
        FALLBACK_SIZE,
    )
}

export default function Image({
    src,
    alt,
    width,
    height,
    sizes,
    className,
    wrapperClassName,
    loading = "lazy",
    ...props
}: ImageProps) {
    imageRegistry.add(src)

    const webpSrcSet = generateSrcSet(src, MODERN_FORMAT)
    const fallbackSrcSet = generateSrcSet(src, FALLBACK_FORMAT)
    const fallbackSrc = generateFallbackSrc(src)

    return (
        <picture className={wrapperClassName}>
            <source
                srcSet={webpSrcSet}
                type={`image/${MODERN_FORMAT}`}
                sizes={sizes}
            />
            <source
                srcSet={fallbackSrcSet}
                type={`image/${FALLBACK_FORMAT}`}
                sizes={sizes}
            />
            <img
                className={className}
                src={fallbackSrc}
                alt={alt}
                width={width}
                height={height}
                loading={loading}
                {...props}
            />
        </picture>
    )
}
